mapper.select:
SELECT sr.id, sr.user_id, sr.equipment_id, sr.request_type, sr.requested_quantity, sr.purpose, sr.urgency, sr.expected_start_date, sr.expected_end_date, sr.status, sr.priority_score, sr.admin_id, sr.decision_reason, sr.processed_at, sr.created_at, sr.updated_at, u.name as user_name, u.username as user_username, e.name as equipment_name, e.category as equipment_category, r.name as reviewer_name FROM special_rental_requests sr LEFT JOIN users u ON sr.user_id = u.id LEFT JOIN equipment e ON sr.equipment_id = e.id LEFT JOIN users r ON sr.admin_id = r.id
AND sr.status = #{params.status}
AND sr.urgency = #{params.urgency}
AND ( u.name LIKE CONCAT('%', #{params.search}, '%') OR u.username LIKE CONCAT('%', #{params.search}, '%') OR e.name LIKE CONCAT('%', #{params.search}, '%') OR sr.purpose LIKE CONCAT('%', #{params.search}, '%') )
ORDER BY CASE WHEN sr.urgency = 'EMERGENCY' THEN 1 WHEN sr.urgency = 'HIGH' THEN 2 WHEN sr.urgency = 'MEDIUM' THEN 3 ELSE 4 END, sr.priority_score DESC, sr.created_at DESC
LIMIT #{params.offset}, #{params.size}

SELECT sr.id, sr.user_id, sr.equipment_id, sr.request_type, sr.requested_quantity, sr.purpose, sr.urgency, sr.expected_start_date, sr.expected_end_date, sr.status, sr.priority_score, sr.admin_id, sr.decision_reason, sr.processed_at, sr.created_at, sr.updated_at, u.name as user_name, u.username as user_username, e.name as equipment_name, e.category as equipment_category, r.name as reviewer_name FROM special_rental_requests sr LEFT JOIN users u ON sr.user_id = u.id LEFT JOIN equipment e ON sr.equipment_id = e.id LEFT JOIN users r ON sr.admin_id = r.id WHERE sr.user_id = #{userId}
AND sr.status = #{params.status}
ORDER BY sr.created_at DESC
LIMIT #{params.offset}, #{params.size}

SELECT FROM special_rental_requests sr
WHERE (sr.urgency_level = 'EMERGENCY' OR sr.is_emergency = true) AND sr.status = 'PENDING' ORDER BY sr.created_at ASC
LIMIT #{params.offset}, #{params.size}

SELECT COUNT(*) FROM special_rental_requests sr LEFT JOIN users u ON sr.user_id = u.id LEFT JOIN equipment e ON sr.equipment_id = e.id
AND sr.status = #{params.status}
AND sr.urgency = #{params.urgency}
AND ( u.name LIKE CONCAT('%', #{params.search}, '%') OR u.username LIKE CONCAT('%', #{params.search}, '%') OR e.name LIKE CONCAT('%', #{params.search}, '%') OR sr.purpose LIKE CONCAT('%', #{params.search}, '%') )

SELECT COUNT(*)
FROM special_rental_requests sr
WHERE sr.user_id = #{userId}

    AND sr.status = #{params.status}

SELECT COUNT(*)
FROM special_rental_requests
WHERE user_id = #{userId}
AND equipment_id = #{equipmentId}
AND status = 'PENDING'

mapper.insert:
INSERT INTO special_rental_attachments (
    special_request_id, original_filename, stored_filename, file_path, file_size, file_type, description
) VALUES (
    #{specialRequestId}, #{originalFilename}, #{storedFilename}, #{filePath}, #{fileSize}, #{fileType}, #{description}
)

INSERT INTO special_rental_logs (
    special_request_id, action_type, action_by, action_reason, previous_status, new_status
) VALUES (
    #{specialRequestId}, #{actionType}, #{actionBy}, #{actionReason}, #{previousStatus}, #{newStatus}
)
